#!/usr/bin/env python3
"""Generate non-circular manifest/sums: sums binds payload plus manifest."""
from __future__ import annotations

import hashlib
import json
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
MANIFEST = ROOT / "10_MANIFEST.json"
SUMS = ROOT / "11_SHA256SUMS"
EXCLUDED = {"10_MANIFEST.json", "11_SHA256SUMS"}


def digest(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def payload_files() -> list[Path]:
    values = []
    for path in ROOT.rglob("*"):
        if not path.is_file():
            continue
        relative = path.relative_to(ROOT).as_posix()
        parts = relative.split("/")
        if relative in EXCLUDED:
            continue
        if "__pycache__" in parts or ".pytest_cache" in parts or path.suffix == ".pyc":
            raise SystemExit(f"forbidden generated artifact: {relative}")
        values.append(path)
    return sorted(values, key=lambda item: item.relative_to(ROOT).as_posix())


def main() -> int:
    files = payload_files()
    entries = [
        {
            "path": path.relative_to(ROOT).as_posix(),
            "bytes": path.stat().st_size,
            "sha256": digest(path),
        }
        for path in files
    ]
    tests_path = ROOT / "tests" / "TEST_COUNTS.json"
    tests = json.loads(tests_path.read_text(encoding="utf-8")) if tests_path.exists() else {}
    document = {
        "schema": "p5-alpha-unblocking-package-manifest/v1",
        "canonical_id": "P5_OWNER_ADMIN_CUTOVER_ALPHA_UNBLOCKING_FL18",
        "status": "CEREMONY_READY_UNEXECUTED",
        "mission_id": "P5-CODEX-FINAL-ALPHA-UNBLOCKING-CLOSURE-V1",
        "supersedes_package_self_sha256": "f1da80801233be0f7f2080f2596c1cb512a0dd377b75cd58e55809c6d09c9e1f",
        "file_count": len(entries),
        "files": entries,
        "test_counts": tests,
        "scientific_rule_changes": {
            "estimand": 0, "adjudication": 0, "candidate": 0,
            "data": 0, "multiplicity": 0,
        },
        "production_mutations_by_engineering_mission": {
            "cutover": False, "schema_migration": False, "c_registered": False,
            "d_registered": False, "root_registered": False,
            "real_labels_read": False, "t1_executed": False, "wave1_executed": False,
        },
        "identity_algorithm": {
            "manifest_enumerates": "all payload files except 10_MANIFEST.json and 11_SHA256SUMS",
            "sums_enumerates": "all payload files plus 10_MANIFEST.json",
            "package_self_sha256": "sha256(11_SHA256SUMS)",
            "line_order": "UTF-8 bytewise relative-path order",
            "line_ending": "LF",
        },
    }
    MANIFEST.write_text(
        json.dumps(document, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        + "\n", encoding="utf-8", newline="\n",
    )
    sum_paths = files + [MANIFEST]
    sum_paths.sort(key=lambda item: item.relative_to(ROOT).as_posix())
    SUMS.write_text(
        "".join(f"{digest(path)}  {path.relative_to(ROOT).as_posix()}\n" for path in sum_paths),
        encoding="utf-8", newline="\n",
    )
    print(json.dumps({
        "payload_files": len(files),
        "manifest_sha256": digest(MANIFEST),
        "sha256sums_sha256": digest(SUMS),
        "package_self_sha256": digest(SUMS),
        "sums_lines": len(sum_paths),
    }, sort_keys=True))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

